package edu.synergy.algorithms.lists;
import java.io.PrintStream;
public final class MyLinkedList { public static final class Node{public final int data;public Node next;public Node(int data){this.data=data;}@Override public String toString(){return "Node{"+"data="+data+", next="+next+'}';}} private Node head; public void add(int value){if(head==null){head=new Node(value);return;}Node current=head;while(current.next!=null)current=current.next;current.next=new Node(value);} public Node findMiddle(){if(head==null)return null;Node slow=head,fast=head;while(fast!=null&&fast.next!=null){slow=slow.next;fast=fast.next.next;}return slow;} public void printReverse(){printReverse(System.out);} public void printReverse(PrintStream out){printReverse(head,out);out.println();} private void printReverse(Node node,PrintStream out){if(node==null)return;printReverse(node.next,out);out.print(node.data+" ");} }
